/// Look up the SVG `<symbol>` viewBox + path data for a codepoint.
pub(super) fn glyph_path(cp: u32) -> Option<(&'static str, &'static str)> {
    GLYPH_PATHS
        .iter()
        .find(|(c, _, _)| *c == cp)
        .map(|(_, vb, d)| (*vb, *d))
}

/// Emit one `<defs>` block containing every glyph in `GLYPH_PATHS` as a
/// `<symbol id="g-XXXX">` with its native viewBox. Renderers reference
/// these via `<use href="#g-XXXX">` so the chart no longer depends on
/// any installed symbol font — every viewer renders identical vector
/// glyphs.
///
/// Symbol fonts have non-square aspect ratios (e.g. Mercury is 1267
/// wide vs 2048 tall); each `<symbol>` carries its own viewBox so the
/// `<use>` element only needs to provide a target size and the
/// `preserveAspectRatio="xMidYMid meet"` set here keeps the glyph
/// centred in whatever bounding box the caller picks. The path `d`
/// attributes carry no `fill` — colour is inherited from `<use fill=…>`.
pub(super) fn emit_defs(s: &mut String) {
    use std::fmt::Write as _;
    let _ = s.write_str("  <defs>\n");
    for (cp, vb, d) in GLYPH_PATHS {
        let _ = writeln!(
            s,
            r##"    <symbol id="g-{cp:04X}" viewBox="{vb}" preserveAspectRatio="xMidYMid meet"><path d="{d}"/></symbol>"##
        );
    }
    // South Node (U+260B) — diametric opposite of the North Node glyph.
    // No separate path table entry: we derive it by flipping the North
    // Node symbol vertically. The wrapping `<g>` mirrors around the
    // viewBox horizontal midline so the resulting glyph keeps the same
    // bounding box as `g-260A` and aligns with surrounding text.
    if let Some((vb, _)) = glyph_path(0x260A) {
        let _ = writeln!(
            s,
            r##"    <symbol id="g-260B" viewBox="{vb}" preserveAspectRatio="xMidYMid meet"><g transform="translate(0,2048) scale(1,-1)"><use href="#g-260A"/></g></symbol>"##
        );
    }
    let _ = s.write_str("  </defs>\n");
}

/// Render `cp` as a `<use>` element centred at `(cx, cy)` with a
/// `size × size` bounding box, filled with `fill`. Returns `false`
/// when the codepoint is missing from `GLYPH_PATHS` so the caller can
/// fall back to a text emission. Trailing variation selectors (e.g.
/// `U+FE0E` / VS15) are tolerated — only the leading char matters.
pub(super) fn write_use(s: &mut String, cp: u32, cx: f64, cy: f64, size: f64, fill: &str) -> bool {
    use std::fmt::Write as _;
    // 0x260B (South Node) has no path-table entry — its `<symbol>` is
    // synthesised by `emit_defs` as a vertical flip of the North Node
    // (0x260A), so it's still referenceable via `<use>` here.
    if cp != 0x260B && glyph_path(cp).is_none() {
        return false;
    }
    let x = cx - size / 2.0;
    let y = cy - size / 2.0;
    let _ = writeln!(
        s,
        r##"  <use href="#g-{cp:04X}" x="{x:.2}" y="{y:.2}" width="{size:.2}" height="{size:.2}" fill="{fill}"/>"##
    );
    true
}

/// Extract the leading code-point of a glyph string. Strings in
/// `BODIES` / `SIGN_GLYPHS` end with `U+FE0E` (text-presentation
/// selector); the selector is irrelevant for the `<use>` lookup so
/// we take just the first `char`.
pub(super) fn lead_cp(g: &str) -> u32 {
    g.chars().next().map_or(0, |c| c as u32)
}
